  if(x.v===7){ x.sounds={}; x.v=8; }                              // v7 → v8: điểm luyện phát âm (cặp âm) theo từng bộ
  if(x.v===8){ x.xp=Math.round((x.stats&&x.stats.c||0)*5); x.freeze={n:0,used:[],earned:0}; x.games={speed:0,match:0,ch:[]}; x.story={}; x.v=9; }   // v8 → v9: XP (tính lại từ số câu đúng), ngày nghỉ phép, trò chơi, truyện
  if(x.v===9){ x.xpd={}; x.rec={combo:0}; x.cos={own:[],skin:'',acc:''}; x.v=10; }   // v9 → v10: XP theo ngày (so tuần), kỷ lục combo, tủ đồ linh vật
  if(x.v===10){ Object.assign(x,{cando:{},dlg:{},fn:{},pron:{},wtask:{},stask:{},lread:{}}); x.v=11; }   // v10 → v11: can-do, hội thoại, chức năng, phát âm cả câu, đề viết/nói, bài đọc dài
  if(x.v===11){ Object.assign(x,{rid:newRid(),me:{},ev:{},oral:{}}); x.v=12; }   // v11 → v12: hồ sơ người học, dữ liệu nghiên cứu ẩn danh (tự nguyện gửi), luyện nói ra từ
  if(x.v===12){ x.nw={}; x.v=13; }   // v12 → v13: đếm từ mới mỗi ngày (giới hạn mềm), độ tự tin trong ev.cal
  if(x.v===13){ const c=x.cos||(x.cos={own:[],skin:'',acc:''}); let L=1; while((x.xp||0)>=100*L*(L+1)/2) L++;   // v13 → v14: phụ kiện/màu mở theo unit vững;
    for(const [k,lv] of [['scarf',2],['glasses',4],['hat',6],['crown',10]]) if(L>=lv&&!c.own.includes(k)) c.own.push(k);   // giữ những món đã mở theo bậc XP
    c.sk=[['forest',3],['sunset',5],['grape',8],['rose',12]].filter(([k,lv])=>L>=lv).map(([k])=>k); x.v=14; }
  if(x.v===14){ x.srs={k:1,n:0}; x.v=15; }   // v14 → v15: nhật ký học ev.log, số lần quên w.lp, ngày qua unit u.pd, hệ số lịch ôn theo người học
  if(x.v===15){ x.money={h:5,hd:0,ht:0}; x.v=16; }   // v15 → v16: tim, gói Super, đếm quảng cáo (docs/DANH-GIA-BEN-VUNG.md)
  if(x.v===16){ x.app={seen:v0<=15?13:14,vh:[]}; x.v=17; }   // v16 → v17: số bản phát hành đã xem (“Có gì mới”), lịch sử đổi bản; người học cũ được báo các bản chưa thấy
  if(x.v===17){ delete x.money; x.x={}; x.v=18; }   // v17 → v18: bỏ tim/Super/quảng cáo (miễn phí 100%); thêm st.x cho phần ôn thi IELTS/VSTEP (mô-đun src/exam)
