/* Ghi âm giọng người học ngay trên máy (MediaRecorder) để tự so với câu mẫu. Không gửi đi đâu, không chấm. */
const HAS_REC = typeof navigator!=='undefined' && !!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia) && typeof MediaRecorder!=='undefined';
const REC = {mr:null,url:null,on:false,keep:false};
async function recStart(){
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true}), chunks=[];
    const mr=new MediaRecorder(stream); REC.mr=mr; REC.keep=true;
    mr.ondataavailable=e=>{ if(e.data&&e.data.size) chunks.push(e.data); };
    mr.onstop=()=>{ stream.getTracks().forEach(t=>t.stop()); REC.on=false;
      if(!REC.keep) return;
      if(REC.url) URL.revokeObjectURL(REC.url);
      REC.url=URL.createObjectURL(new Blob(chunks,{type:mr.mimeType||'audio/webm'})); if(['speak','rp','stask','pronsh','vx','spk'].includes(ui.view)) render(); };
    mr.start(); REC.on=true; render();
  }catch(e){ REC.on=false; toast('Không mở được micro. Bạn vẫn có thể nói to rồi tự đánh giá.'); render(); }
}
function recStop(){ try{ if(REC.mr&&REC.mr.state!=='inactive') REC.mr.stop(); }catch(e){} }
function recPlay(){ if(!REC.url) return; try{ if(HAS_TTS) speechSynthesis.cancel(); new Audio(REC.url).play(); }catch(e){} }
function recReset(){ REC.keep=false; recStop(); if(REC.url){ try{URL.revokeObjectURL(REC.url);}catch(e){} } REC.url=null; REC.on=false; }

/* ---------- Máy nghe giọng (docs/DANH-GIA-SO-VOI-THI-TRUONG.md, tiêu chí 6) ----------
   Dùng nhận diện giọng nói có sẵn của trình duyệt (Web Speech API) để cho biết máy nghe ra những từ nào của câu mẫu.
   Không phải chấm phát âm kiểu AI: “máy nghe ra” ≈ người nghe hiểu được bạn. Chỉ chạy khi người học đã đồng ý (st.set.asr),
   vì trình duyệt có thể gửi âm thanh tới máy chủ nhận diện của hãng (Chrome/Edge); app không lưu âm thanh, không gửi gì khác.
   Chỉ là phản hồi: không đổi mức thuộc, lịch ôn hay XP. Đếm số lần dùng ở ev.c (asr, asr:ok), không lưu nội dung. */
const SPEECH_REC = typeof window!=='undefined' ? (window.SpeechRecognition||window.webkitSpeechRecognition||null) : null;
const HAS_ASR = !!SPEECH_REC;
const ASR = {on:false,key:'',res:null,err:'',r:null,pending:null};
function asrReset(){ const r=ASR.r; Object.assign(ASR,{on:false,key:'',res:null,err:'',r:null}); try{ r&&r.abort(); }catch(e){} }
// So câu máy nghe được với câu mẫu (dãy con chung dài nhất theo từ): từ nào của câu mẫu máy nghe ra. Chọn phương án nghe khớp nhất.
function asrMatch(target,heard){
  const b=gsent(target).split(' ').filter(Boolean); let best={n:-1,hit:[],heard:''};
  for(const h of heard){ const a=gsent(h).split(' ').filter(Boolean);
    const T=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
    for(let i=a.length-1;i>=0;i--) for(let j=b.length-1;j>=0;j--) T[i][j]=a[i]===b[j]?T[i+1][j+1]+1:Math.max(T[i+1][j],T[i][j+1]);
    const hit=[]; let i=0,j=0; while(i<a.length&&j<b.length){ if(a[i]===b[j]){ hit.push(j); i++; j++; } else if(T[i+1][j]>=T[i][j+1]) i++; else j++; }
    if(hit.length>best.n) best={n:hit.length,hit,heard:h}; }
  return {words:b,hit:best.hit,heard:best.heard,p:b.length?Math.max(0,best.n)/b.length:0};
}
// Một từ (cặp âm tối thiểu, nói ra từ): máy nghe ra đúng từ, nghe thành từ kia của cặp, hay không rõ.
function asrWord(target,other,heard){
  const has=w=>heard.some(h=>gsent(h).split(' ').includes(gsent(w)));
  return {word:true,k:has(target)?'ok':other&&has(other)?'other':'unclear',heard:heard[0]||''};
}
const ASR_ERR = {'not-allowed':'Trình duyệt chưa cho dùng micro (trình xem artifact luôn chặn). Mở bản web của app và cho phép micro.','service-not-allowed':'Trình duyệt này không cho nhận diện giọng nói ở đây. Hãy thử Chrome hoặc Edge, mở bản web của app.',
  'no-speech':'Máy chưa nghe thấy gì. Bấm lại rồi nói ngay.','audio-capture':'Không tìm thấy micro.','network':'Nhận diện giọng cần mạng (trình duyệt gửi âm thanh đi nhận diện).'};
function asrStart(key,target,other){
  if(!HAS_ASR) return;
  if(st.set.asr!==true){ ASR.pending={key,target,other}; return modal({ic:'🎙',title:'Bật máy nghe giọng?',html:true,
    sub:'Bạn nói, máy của trình duyệt nghe và cho biết nó nghe ra những từ nào: người nghe có hiểu bạn không. Đây <b>không phải</b> chấm phát âm chuẩn như giáo viên.<br><br>Để nhận diện, trình duyệt <b>có thể gửi âm thanh tới máy chủ của hãng trình duyệt</b> (Chrome, Edge thường gửi; Safari có khi nhận diện ngay trên máy). English Ladder không lưu và không gửi gì khác. Tắt được bất cứ lúc nào trong Cài đặt.',
    buttons:[{label:'Đồng ý, bật',act:'asrok',primary:true},{label:'Không',act:'mclose'}]}); }
  recStop(); asrReset();
  let r; try{ r=new SPEECH_REC(); }catch(e){ toast('Trình duyệt này chưa nhận diện được giọng nói.'); return; }
  r.lang='en-US'; r.interimResults=false; r.maxAlternatives=5; r.continuous=false;
  Object.assign(ASR,{on:true,key,r,res:null,err:''});
  r.onresult=e=>{ if(ASR.r!==r) return; const res=e.results||[], alts=[];
    if(res[0]) for(let j=0;j<res[0].length;j++) alts.push(res[0][j].transcript);
    if(res.length>1) alts.unshift(Array.from(res).map(x=>x[0].transcript).join(' '));
    ASR.res=target==='*'?{free:true,heard:alts[0]||'',alts,p:1,k:'ok'}:/\s/.test(target.trim())?asrMatch(target,alts):asrWord(target,other,alts); ASR.on=false;   // '*': nghe tự do (v84 Robot: lệnh)
    evc('asr'); if(ASR.res.word?ASR.res.k==='ok':ASR.res.p>=.8) evc('asr:ok'); save(); render(); };
  r.onerror=e=>{ if(ASR.r!==r) return; ASR.err=ASR_ERR[e.error]||'Máy chưa nhận diện được lần này. Thử lại.'; ASR.on=false; render(); };
  r.onend=()=>{ if(ASR.r!==r||!ASR.on) return; ASR.on=false; if(!ASR.res&&!ASR.err) ASR.err=ASR_ERR['no-speech']; render(); };
  try{ r.start(); }catch(e){ ASR.on=false; ASR.err='Máy chưa nhận diện được lần này. Thử lại.'; }
  render();
}
// Nút + kết quả. key phân biệt từng câu; other = từ kia của cặp âm (chỉ với một từ).
function asrBox(key,target,other,label){
  if(!HAS_ASR||!target) return '';
  const mine=ASR.key===key, r=mine&&ASR.res, attrs=`data-act="asr" data-k="${esc(key)}" data-t="${esc(target)}"${other?` data-o="${esc(other)}"`:''}`;
  if(mine&&ASR.on) return `<div class="row"><button class="btn" data-act="asrstop">■ Đang nghe… bấm khi nói xong</button></div>`;
  const btn=`<button class="btn" ${attrs}>🎙 ${r||(mine&&ASR.err)?'Nói lại':esc(label||'Nói để máy nghe')}</button>`;
  if(mine&&ASR.err) return `<div class="stack" style="gap:6px"><div class="row">${btn}</div><p class="hint" role="status">${esc(ASR.err)}</p></div>`;
  if(!r) return `<div class="row">${btn}</div>`;
  let body;
  if(r.word){ const o=esc(other||'');
    body=r.k==='ok'?`<div class="fb good" role="status"><strong>Máy nghe ra đúng “<span lang="en">${esc(target)}</span>”</strong></div>`
      :r.k==='other'?`<div class="fb bad" role="status"><strong>Máy nghe thành “<span lang="en">${o}</span>”</strong><span>Âm bạn nói gần với từ kia của cặp. Nghe mẫu, đọc mẹo rồi nói lại.</span></div>`
      :`<div class="fb neutral" role="status"><strong>Máy chưa nghe ra “<span lang="en">${esc(target)}</span>”</strong><span>Máy nghe được: “<span lang="en">${esc(r.heard)||'…'}</span>”. Nói chậm, rõ âm cuối rồi thử lại.</span></div>`;
  } else {
    const hit=new Set(r.hit), n=hit.size, all=r.words.length;
    body=`<div class="fb ${r.p>=.8?'good':r.p>=.5?'neutral':'bad'}" role="status"><strong>Máy nghe ra ${n}/${all} từ</strong>
      <p lang="en" style="font:400 18px/1.5 var(--display)">${r.words.map((w,i)=>`<span class="${hit.has(i)?'asr-ok':'asr-miss'}">${esc(w)}</span>`).join(' ')}</p>
      <span class="hint">Máy nghe được: “<span lang="en">${esc(r.heard)||'…'}</span>”</span>
      <span>${r.p>=.9?'Rất rõ: máy hiểu gần như cả câu.':r.p>=.5?'Nghe lại mẫu, chú ý từ gạch đỏ (thường là âm cuối hoặc trọng âm), rồi nói lại.':'Máy chưa nghe ra phần lớn câu. Nói chậm hơn, gần micro, ở chỗ yên tĩnh.'}</span></div>`;
  }
  return `<div class="stack" style="gap:6px">${body}<div class="row">${btn}</div><p class="hint">Máy nghe ra chưa chắc là phát âm chuẩn; đây là phép thử “người nghe có hiểu bạn không”.</p></div>`;
}

function viewSpeak(){
  const S=ui.speak, u=UNITS.find(x=>x.id===S.uid);
  if(S.i>=S.items.length){
    return `<button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button>
    <section class="stack"><span class="eyebrow">Luyện nói · tự đánh giá</span><h1>Xong ${S.items.length} câu</h1>
    <p class="muted note">Kết quả: ${['hard','ok','easy'].map(k=>`${{hard:'Khó',ok:'Được',easy:'Dễ'}[k]} ${S.rates.filter(r=>r===k).length}`).join(' · ')}. App không chấm độ chuẩn phát âm; nó ghi lại cảm nhận của bạn${HAS_ASR?', còn nút 🎙 cho biết máy nghe ra bao nhiêu từ':''}.</p></section>
    <div class="row"><button class="btn primary" data-act="speak" data-u="${u.id}">Luyện thêm 5 câu</button><button class="btn" data-act="speak" data-u="${u.id}" data-n="10">Luyện cả ${u.words.length} câu</button><button class="btn" data-unit="${u.id}">Về unit</button></div>`;
  }
  const w=S.items[S.i];
  const steps=[['Nghe','Nghe câu mẫu'],['Xem câu','Đọc transcript'],['Nghe lại','Vừa nghe vừa nhìn'],['Che câu','Transcript bị che'],['Tự nói','Nói to cả câu'],['Đánh giá','So sánh & tự chấm']];
  const show = S.step===1||S.step===2||S.step===5;
  const instr=['Bấm nghe câu mẫu. Chưa nhìn câu.','Đọc câu trong lúc nhớ lại âm thanh.','Nghe lại một lần nữa và nhìn theo.','Câu đã được che. Nhẩm lại trong đầu.','Nói to cả câu, không nhìn. Có thể bấm nghe nếu quên.','Đây là câu gốc. Bạn nói lại có dễ không?'][S.step];
  const recBtns = !HAS_REC ? '' : S.step===4
    ? (REC.on ? `<button class="btn" data-act="recstop">■ Dừng ghi âm</button>` : `<button class="btn" data-act="recstart">● Ghi âm giọng bạn</button>`)
    : S.step===5 && REC.url ? `<button class="btn" data-act="recplay">▶ Nghe giọng bạn</button>` : '';
  return `<div class="spread"><button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button><span class="num muted">Câu ${S.i+1}/${S.items.length}</span></div>
  <section class="q">
    <div class="sp-steps">${steps.map((x,i)=>`<div class="${i===S.step?'on':i<S.step?'past':''}">${i+1}. ${x[0]}<br><span>${x[1]}</span></div>`).join('')}</div>
    <p class="transcript ${show?'':'hide'}" aria-hidden="${show?'false':'true'}" lang="en">${show?highlight(w.ex,w):'&nbsp;'}</p>
    <p class="muted">${instr}</p>
    ${S.step>=4?asrBox('sp'+S.i,w.ex):''}
    ${S.step===5?`<div class="row">${HAS_TTS?`<button class="btn" data-say="${esc(w.ex)}">${SPK} Nghe mẫu</button>`:''}${recBtns}</div>
      ${REC.url?'<p class="hint">Nghe mẫu rồi nghe giọng bạn: so trọng âm, âm cuối và chỗ ngắt hơi.</p>':''}
      <div class="rate"><button class="btn" data-rate="hard">Khó</button><button class="btn" data-rate="ok">Được</button><button class="btn" data-rate="easy">Dễ</button></div>`
      :`<div class="row">${HAS_TTS?`<button class="btn" data-say="${esc(w.ex)}">${SPK} Nghe</button><button class="btn" data-say="${esc(w.ex)}" data-slow="1">🐢 Nghe chậm</button>`:'<span class="hint">Trình duyệt này không có giọng đọc; hãy đọc câu mẫu thay cho bước nghe.</span>'}${recBtns}<button class="btn primary" data-act="spnext" ${REC.on?'disabled':''}>Bước tiếp →</button></div>`}
  </section>`;
}

function viewWrite(){
  const u=UNITS.find(x=>x.id===ui.unitId), saved=st.write[u.id]||[], g=u.guided, done=U(u.id).written;
  // Không chấm câu tự do; chỉ đối chiếu máy móc: câu nào đã dùng từ của unit (khớp gốc từ, kể cả dạng -s/-ed/-ing).
  const used = saved.map(x=>u.words.filter(w=>stemRe(w).test(x||'')));
  const usedAll=[...new Set(used.flat())];
  return `<button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button>
  <section class="stack"><span class="eyebrow">Viết theo khung</span><h1>Viết về <span lang="en">${esc(u.title.toLowerCase())}</span></h1>
  <p class="muted note">Điền vào khung câu, cố dùng ít nhất một từ của unit trong mỗi câu. App không chấm câu tự do; sau khi lưu, app chỉ cho biết bạn đã dùng từ nào và hiện câu mẫu để bạn tự so sánh.</p>
  <p class="hint" lang="en">${u.words.map(w=>esc(w.word)).join(' · ')}</p></section>
  <form class="panel gw" data-form="write">
    ${g.lines.map((ln,i)=>{const [a,b]=ln.split('___');return `<label for="gw-${u.id}-${i}" lang="en">${esc(a)}<input id="gw-${u.id}-${i}" value="${esc(saved[i]||'')}" autocomplete="off" lang="en">${esc(b)}</label>`}).join('')}
    <div class="row"><button class="btn primary">Lưu bài viết</button></div>
  </form>
  ${done?`<section class="panel stack"><div class="spread"><h3>Từ của unit bạn đã dùng</h3><span class="pill ${usedAll.length>=3?'good':'warn'}">${usedAll.length}/${u.words.length} từ</span></div>
  <p lang="en">${usedAll.length?usedAll.map(w=>`<mark>${esc(w.word)}</mark>`).join(' '):'<span class="muted">Chưa dùng từ nào của unit. Thử viết lại, dùng một từ trong danh sách phía trên.</span>'}</p>
  <h3 style="margin-top:6px">Câu mẫu để đối chiếu</h3>${g.model.map(m=>`<p class="ex" lang="en">${esc(m)}</p>`).join('')}
  <h3 style="margin-top:6px">Bài của bạn</h3>${g.lines.map((ln,i)=>`<p class="ex" lang="en">${esc(ln.replace('___',saved[i]||'…'))}${saved[i]&&!used[i].length?' <span class="pill warn" lang="vi">chưa dùng từ của unit</span>':''}</p>`).join('')}
  ${hintsHtml(g.lines.map((ln,i)=>ln.replace('___',saved[i]||'')).join(' '))}</section>`:''}
  ${viewSentences(u)}`;
}
// Đặt câu với từng từ: app kiểm tra phần máy kiểm được (có dùng đúng từ, đủ dài, viết hoa đầu câu, có dấu câu),
// rồi đưa câu mẫu + lưu ý để người học tự đối chiếu nghĩa và cách dùng. Không chấm nghĩa (không dùng AI).
function sentenceChecks(w,x){
  const t=(x||'').trim();
  return [
    [stemRe(w).test(t),`Có dùng “${w.word}”`],
    [t.split(/\s+/).filter(Boolean).length>=4,'Ít nhất 4 từ'],
    [/^[A-Z0-9"“]/.test(t),'Viết hoa chữ đầu câu'],
    [/[.!?]["”]?$/.test(t),'Có dấu câu ở cuối']
  ];
}
function viewSentences(u){
  const S=st.write[u.id+':s']||{text:{},self:{}}, checked=ui.sentChecked===u.id;
  const done=u.words.filter(w=>S.text[w.id]&&sentenceChecks(w,S.text[w.id]).every(c=>c[0])).length;
  return `<section class="stack"><div class="spread"><h2>Đặt câu với từng từ</h2><span class="pill ${done===u.words.length?'good':'accent'}">${done}/${u.words.length} câu đạt yêu cầu</span></div>
  <p class="muted note">Viết một câu của riêng bạn cho mỗi từ. App kiểm tra hình thức; sau đó bạn so với câu mẫu và phần “Lưu ý”, rồi tự đánh dấu.</p></section>
  <form class="panel stack" data-form="sent">
    ${u.words.map(w=>{const x=S.text[w.id]||'', cs=sentenceChecks(w,x), me=S.self[w.id]||{};
      return `<div class="stack" style="gap:6px;border-bottom:1px solid var(--line);padding-bottom:12px">
        <label for="se-${w.id}"><b lang="en">${esc(w.word)}</b> <span class="muted">· ${esc(w.vi)}</span></label>
        <div class="row" style="flex-wrap:nowrap"><input id="se-${w.id}" data-w="${w.id}" class="field" style="font:400 16px/1.3 var(--body)" lang="en" value="${esc(x)}" autocomplete="off" placeholder="Câu của bạn…">${x&&HAS_TTS?`<button type="button" class="audio" data-say="${esc(x)}" aria-label="Nghe câu của bạn" title="Nghe câu của bạn">${SPK}</button>`:''}</div>
        ${checked&&x?`<div class="row" style="gap:6px">${cs.map(([ok,l])=>`<span class="pill ${ok?'good':'bad'}">${ok?'✓':'✗'} ${l}</span>`).join('')}</div>
          ${grammarHints(x).map(h=>`<p class="gerr"><span class="pill warn">Lỗi hay gặp</span> <span class="hint">${esc(h.why)}</span></p>`).join('')}
          <p class="hint">Câu mẫu: <span lang="en">${esc(w.ex)}</span></p>${tipBox(w)}
          <div class="row" style="gap:12px;font-size:14px">${[['m','Đúng nghĩa như câu mẫu'],['u','Đã tránh lỗi trong “Lưu ý”']].map(([k,l])=>`<label><input type="checkbox" data-self="${w.id}:${k}" ${me[k]?'checked':''}> ${l}</label>`).join('')}</div>`:''}
      </div>`;}).join('')}
    <div class="row"><button class="btn primary">Kiểm tra &amp; lưu</button></div>
  </form>`;
}

function viewArch(){
  const sample=WORD.delicious;
  const eng=(t,d,items)=>`<div class="engine"><div class="stack" style="gap:2px"><h3>${t}</h3><span class="hint">${d}</span></div><div class="items">${items.map(x=>`<span class="pill">${x}</span>`).join('')}</div></div>`;
  return `<section class="stack"><span class="eyebrow">Content-driven architecture</span><h1>Kiến trúc demo</h1>
  <p class="muted note">Không AI, không API, không chi phí inference. Engine được code một lần; A1 hay C2 chỉ là dữ liệu. Trang này đọc trực tiếp từ dữ liệu đang chạy.</p></section>
  <section class="engines">
    ${eng('Content engine','Dữ liệu authoring sẵn',['word','meaning','part of speech','IPA + trọng âm','picture','audio','example + dịch','tip','why (giải thích từng nhiễu)','cloze','collocations','forms (word family)','CEFR','topic'])}
    <span class="arrow"></span>
    ${eng('Curriculum engine','Level → Unit → Lesson',[`${CONTENT.levels.length} level`,`${UNITS.length} unit`,`${ALL_WORDS.length} từ`,'mở khoá tuần tự',`qua unit ≥ ${pct(PASS)}`])}
    <span class="arrow"></span>
    ${eng('Practice engine','Sinh bài từ dữ liệu, khó dần',['Recognition','Listening','Recall (chọn → gõ)','Spelling','Dictation','Fill blank (chọn → gõ)','Sentence building','Collocation','Controlled speaking + ghi âm','Guided writing'])}
    <span class="arrow"></span>
    ${eng('Mastery engine','Điểm, SRS, điểm yếu',['5 kỹ năng / từ','ưu tiên kỹ năng yếu','SRS 1→60 ngày','remediation','thi vượt cấp','mục tiêu ngày','tiến độ'])}
  </section>
  <section class="stack"><h2>Vòng học của một unit</h2>
    <div class="flow"><span>Learn</span><em>→</em><span>Practice</span><em>→</em><span>Speak / Write</span><em>→</em><span>Unit Test (20 câu)</span><em>→</em><span>≥ ${pct(PASS)} và mỗi kỹ năng ≥ ${pct(DIM_MIN)}?</span><em>có →</em><span>Unit tiếp theo</span><em>· không →</em><span>Remediation</span><em>→</em><span>Thi lại</span></div>
  </section>
  <section class="two">
    <div class="stack"><h3>Một từ trong Content schema</h3><pre>${esc(JSON.stringify({cefr:UNIT_OF.delicious.level,unit:UNIT_OF.delicious.id,...sample},null,2))}</pre></div>
    <div class="stack"><h3>Tiến độ của từ đó (User Progress)</h3><pre>${esc(JSON.stringify(W('delicious'),null,2))}</pre>
      <p class="note"><code>d</code>: điểm 0–1 cho 5 kỹ năng (null = chưa kiểm tra). <code>stage</code>: bậc SRS. <code>due</code>: số ngày tuyệt đối đến hạn ôn.</p></div>
  </section>
  <section class="stack"><h2>Mỗi dạng bài dùng trường dữ liệu nào</h2>
  <div class="tablewrap"><table><thead><tr><th>Dạng bài</th><th>Kỹ năng ghi điểm</th><th>Trường dữ liệu</th><th>Phương án nhiễu lấy từ</th></tr></thead><tbody>
    <tr><td>Word → Meaning</td><td>Recognition</td><td class="num">word, en</td><td>nghĩa của từ khác cùng unit</td></tr>
    <tr><td>Sentence → Meaning</td><td>Recognition</td><td class="num">ex, exVi</td><td>bản dịch câu của từ khác cùng unit</td></tr>
    <tr><td>Listening</td><td>Recognition</td><td class="num">word (audio)</td><td>từ khác cùng unit</td></tr>
    <tr><td>Meaning → Word</td><td>Recall (điểm &lt; ${pct(HARD)})</td><td class="num">en, vi, word</td><td>từ khác cùng unit</td></tr>
    <tr><td>Meaning → Type</td><td>Recall (điểm ≥ ${pct(HARD)}, bài test)</td><td class="num">en, vi, word</td><td>không cần (tự gõ)</td></tr>
    <tr><td>Spelling</td><td>Spelling</td><td class="num">word</td><td>không cần (che 40% → 70% chữ)</td></tr>
    <tr><td>Dictation</td><td>Spelling (điểm ≥ ${pct(HARD)}, bài test)</td><td class="num">word (audio)</td><td>không cần (tự gõ)</td></tr>
    <tr><td>Fill the blank</td><td>Context</td><td class="num">cloze.s, cloze.a</td><td class="num">cloze.w (authoring sẵn)</td></tr>
    <tr><td>Word family (chọn → gõ)</td><td>Context</td><td class="num">forms</td><td>dạng khác cùng họ + từ gốc (khác loại từ/nghĩa)</td></tr>
    <tr><td>Type in context</td><td>Context (điểm ≥ ${pct(HARD)}, bài test)</td><td class="num">ex</td><td>không cần (gõ đúng dạng từ)</td></tr>
    <tr><td>Sentence building</td><td>Context</td><td class="num">ex</td><td>không cần (xáo từ)</td></tr>
    <tr><td>Collocation</td><td>Collocation</td><td class="num">col.ok</td><td class="num">col.bad (authoring sẵn)</td></tr>
    <tr><td>Controlled speaking</td><td>Tự đánh giá (không tính)</td><td class="num">ex (audio)</td><td>—</td></tr>
    <tr><td>Guided writing</td><td>Không chấm</td><td class="num">unit.guided</td><td>—</td></tr>
  </tbody></table></div>
  <p class="note">Phương án nhiễu cho điền chỗ trống và collocation được viết tay, vì lấy ngẫu nhiên dễ tạo ra câu vẫn đúng. Âm thanh trong demo dùng giọng đọc có sẵn của trình duyệt; bản thật nên dùng file audio thu sẵn.</p></section>
  <section class="two">
    <div class="panel stack"><h3>Công thức mastery</h3><pre>score[k] ← score[k] + a × (đúng ? 1 − score[k] : 0 − score[k])
  a = 0.3 khi chọn đúng câu trắc nghiệm (có thể đoán), 0.5 khi tự gõ đúng hoặc trả lời sai
mastery(từ) = trung bình 5 kỹ năng
mastery(unit) = trung bình các từ
đã thuộc: mastery ≥ ${MASTERED} và bậc SRS ≥ ${LONG_TERM}
kỹ năng ≥ ${HARD} → chuyển sang dạng tự gõ</pre></div>
    <div class="panel stack"><h3>Lịch ôn FSRS-5</h3><pre>mỗi thẻ: độ bền S (ngày), độ khó D (1–10), ngày ôn gần nhất
đến hạn khi khả năng nhớ R(t) = (1 + 19/81 · t / S)^−0,5 giảm còn 90%
đúng khi đến hạn: S tăng (tự gõ đúng = "được", chọn đúng trắc nghiệm = "khó"), khoảng ôn = f(S) × hệ số riêng (tối đa ${MAX_IVL} ngày)
sai: S giảm theo FSRS, D tăng, lùi 2 bậc, ôn lại ngày mai</pre><p class="note">Luyện tập trước hạn cập nhật mastery nhưng không đổi lịch.</p></div>
  </section>`;
}

/* ---------- Sao lưu & nhắc học (không cần server) ---------- */
// Trong trình xem artifact của claude.ai, tải file phải qua capability "downloads"; mở file trực tiếp thì dùng link blob.
const IN_VIEWER = typeof window!=='undefined' && !!(window.claude && typeof window.claude.use==='function');
// Chỉ hứa “dùng khi mất mạng” khi service worker thật sự đăng ký được (qua http/https, không trong trình xem artifact) — cùng điều kiện với chỗ đăng ký sw.js.
const CAN_OFFLINE = typeof location!=='undefined' && /^https?:$/.test(location.protocol) && !IN_VIEWER && typeof navigator!=='undefined' && 'serviceWorker' in navigator;
async function download(name,text,type){
  if(IN_VIEWER){
    let dl=null; try{ dl=await window.claude.use('downloads'); }catch(e){}
    if(dl){ try{ await dl.save({filename:name,data:text}); return true; }
      catch(e){ if(!e||e.code!=='declined') toast('Không tải được file trong trang này.'); return false; } }
  }
  try{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type})); a.download=name; document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500); }
  catch(e){ toast('Trình duyệt không cho tải file.'); return false; }
  return true;
}
// v53 (spec v2.4 §88): sổ bằng chứng trên máy + bản xuất nghiên cứu đầy đủ (quan sát thô, sổ L1, thống kê, luật, provenance).
function evPanel(){ const e=st.e||{}, v=e.ev||{}, ig=v.integ||{}, n=(v.led||[]).length, crit=(v.led||[]).filter(x=>x.tier>=2).length, kb=Math.round(JSON.stringify(v).length/1024);
  return `<p class="note">Sổ bằng chứng trên máy này: ${n} sự kiện gần đây (${crit} quan trọng), ${kb} KB. Luật đang dùng: ${esc(ELCORE.rules.id)}.${ig.err?` Lỗi ghi: ${ig.err}.`:''}${ig.fixed?` Đã tự sửa ${ig.fixed} ô lệch.`:''} Bằng chứng ít giá trị được gộp thành thống kê, bằng chứng quan trọng được giữ.</p>
    ${(()=>{ try{ const a=ELCORE.audit(st,today()), d=a.drift, x=a.est, f=v=>v==null?'chưa đủ dữ liệu':String(v).replace('.',',');
      return `<p class="hint">Kiểm toán model trên dữ liệu của bạn: ${d.n>=20?`14 ngày qua ở các phần đã Đạt, đúng ${Math.round(d.obs*100)}% so với dự đoán ${Math.round(d.exp*100)}%${d.flag?' — <b>model đang lạc quan quá, app sẽ kiểm lại</b>':' (khớp)'}`:'chưa đủ lượt để kiểm trôi'}. Ước lượng tỉ lệ sai khi đã biết (slip): ${f(x.slip)} (luật dùng 0,1); đúng nhờ đoán: ${f(x.guess)}${x.guessTheory!=null?` (lý thuyết ${f(x.guessTheory)})`:''}. Chỉ báo cáo, không tự đổi luật.</p>`; }catch(e){ return ''; } })()}
    <div class="row"><button class="btn" data-act="evexport">Tải dữ liệu nghiên cứu đầy đủ</button><button class="btn ghost" data-act="msgo">📏 Đo tiến bộ</button></div>
    <label class="row" style="gap:8px"><input type="checkbox" data-act="research" ${st.set.research?'checked':''}> <span>Tham gia nghiên cứu: gán nhãn nhóm so sánh (thích ứng / cố định, game / không game) vào dữ liệu nghiên cứu khi bạn đo tiến bộ. Không đổi trải nghiệm học; dữ liệu chỉ rời máy khi bạn tự tải và gửi.</span></label>`; }
async function exportResearch(){ const d=new Date().toISOString().slice(0,10);
  await download(`english-ladder-research-${d}.json`,JSON.stringify(ELCORE.research(st),null,1),'application/json'); }
async function exportBackup(){
  const d=new Date().toISOString().slice(0,10);
  if(await download(`vocab-ladder-${d}.json`,JSON.stringify({app:'vocab-ladder',saved:new Date().toISOString(),state:st},null,1),'application/json')){
    st.set.lastBackup=today(); save(); render();
  }
}
// Mã sao lưu dạng chữ: sao chép rồi dán sang máy khác (qua Zalo, email…) để chuyển tiến độ mà không cần file.
// Nén gzip khi trình duyệt hỗ trợ (tiền tố VL2:), không thì chỉ mã hoá base64 (VL1:).
const b64 = bytes => { let x=''; for(let i=0;i<bytes.length;i+=0x8000) x+=String.fromCharCode.apply(null,bytes.subarray(i,i+0x8000)); return btoa(x); };
const unb64 = t => Uint8Array.from(atob(t),c=>c.charCodeAt(0));
async function makeCode(obj=st){
  const raw=new TextEncoder().encode(JSON.stringify(obj));
  if(typeof CompressionStream!=='undefined'){ try{ const buf=await new Response(new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer(); return 'VL2:'+b64(new Uint8Array(buf)); }catch(e){} }
  return 'VL1:'+b64(raw);
}
async function readCode(code){
  const c=String(code).trim().replace(/\s+/g,''), kind=c.slice(0,4), bytes=unb64(c.slice(4));
  let text;
  if(kind==='VL2:') text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  else if(kind==='VL1:') text=new TextDecoder().decode(bytes);
  else throw new Error('bad');
  return migrate(JSON.parse(text));
}
async function copyCode(){
  const code=await makeCode(); ui.backupCode=code; st.set.lastBackup=today(); save();
  let ok=false; try{ await navigator.clipboard.writeText(code); ok=true; }catch(e){}
  if(ok) toast(`Đã sao chép mã sao lưu (${Math.round(code.length/1024)} KB). Dán vào Cài đặt → Khôi phục bằng mã trên máy kia.`);
  else { toast('Trình duyệt chặn sao chép tự động: hãy chọn và sao chép mã trong ô bên dưới.'); if(ui.view!=='settings') return go('settings'); }
  render();
}
// Gộp hai trạng thái (máy này + bản sao lưu): mỗi từ/unit/bài giữ bản tiến xa hơn, số đếm lấy lớn nhất, danh sách lấy hợp.
// Học trên điện thoại rồi nạp bản cũ từ máy tính không còn làm mất phần mới (docs/DANH-GIA-KY-THUAT.md).
function mergeState(a,b){
  const x=JSON.parse(JSON.stringify(a)), better=(p,q)=>!q?p:!p?q:(+!!q.passed-+!!p.passed||+!!q.learned-+!!p.learned||(q.stage||0)-(p.stage||0)||(q.ivl||0)-(p.ivl||0)||(q.best||0)-(p.best||0))>0?q:p;
  for(const k of ['words','units','gram','levels','glevels']){ x[k]=x[k]||{}; for(const [id,v] of Object.entries(b[k]||{})) x[k][id]=better(x[k][id],v); }
  x.xp=Math.max(a.xp||0,b.xp||0); x.stats={a:Math.max(a.stats.a,b.stats.a),c:Math.max(a.stats.c,b.stats.c)};
  x.days=[...new Set([...(a.days||[]),...(b.days||[])])].sort((p,q)=>p-q);
  for(const k of ['daily','xpd']){ x[k]={...(a[k]||{})}; for(const [d,n] of Object.entries(b[k]||{})) x[k][d]=Math.max(x[k][d]||0,n); }
  x.hist={...(a.hist||{})}; for(const [d,v] of Object.entries(b.hist||{})){ const u=x.hist[d]||[]; x.hist[d]=v.map((n,i)=>Math.max(n,u[i]||0)); }
  x.badges=[...new Set([...(a.badges||[]),...(b.badges||[])])];
  x.cos={...a.cos,own:[...new Set([...(a.cos.own||[]),...(b.cos.own||[])])],sk:[...new Set([...(a.cos.sk||[]),...(b.cos.sk||[])])]};
  x.games={...a.games,speed:Math.max(a.games.speed||0,b.games.speed||0),match:[a.games.match,b.games.match].filter(Boolean).sort((p,q)=>p-q)[0]||0,ch:[...(a.games.ch||[]),...(b.games.ch||[])].sort((p,q)=>q.day-p.day).slice(0,10)};
  x.start=Math.min(a.start??1e9,b.start??1e9); x.onboarded=true; x.money=moneyMerge(a.money,b.money); if(!(a.me&&a.me.who)&&b.me) x.me=b.me;
  for(const k of ['story','cando','dlg','fn','pron','lread','sounds','wtask','stask','oral','gwrite','lis','shadow','rx','pv','med','sp','pa']) x[k]={...(b[k]||{}),...(a[k]||{})};
  { const seen=new Set(); x.exam=[...(a.exam||[]),...(b.exam||[])].filter(e=>{ const k=JSON.stringify(e); return seen.has(k)?false:seen.add(k); }).sort((p,q)=>q.day-p.day).slice(0,10); }
  x.app={seen:Math.max((a.app||{}).seen||0,(b.app||{}).seen||0),vh:((a.app||{}).vh||[]).slice()};
  x.e=typeof ELCORE!=='undefined'?ELCORE.merge(a.e,b.e):EM?EM.merge(a.e,b.e):((a.e&&(a.e.goals||[]).length?a.e:b.e)||{});   // engine: hợp mục tiêu hai máy
  x.x=XM?XM.merge(a.x,b.x):((a.x&&a.x.attempts||[]).length>=((b.x&&b.x.attempts)||[]).length?a.x:b.x)||{};   // phần ôn thi: mô-đun gộp (lịch sử lấy hợp); chưa nạp thì giữ bản nhiều bài hơn
  { const seen=new Set(); x.ev={...(a.ev||{}),log:[...((b.ev||{}).log||[]),...((a.ev||{}).log||[])].filter(e=>{ const k=JSON.stringify(e); return seen.has(k)?false:seen.add(k); }).sort((p,q)=>p[0]-q[0]).slice(-LOG_MAX)}; }   // bỏ mục trùng: đồng bộ gộp nhiều lần
  return x;
}
// Khôi phục từ mã/file: lọc cấu trúc, rồi hỏi gộp (mặc định) hay thay hẳn.
function applyRestore(x,src){
  x=sanitizeState(x); if(!x||!x.words||!x.units) throw 0;
  const has=ALL_WORDS.some(w=>(st.words[w.id]||{}).learned)||st.stats.a>0;
  const done=(y,how)=>{ st=y; evc('restore'); st.onboarded=true; save(); ui.backupCode=null; closeModal(); toast(`Đã ${how} tiến độ từ ${src}.`); go('path'); };
  if(!has) return done(x,'khôi phục');
  ui.pendingRestore={x,src,done};
  modal({ic:'🔀',title:'Gộp hay thay tiến độ?',sub:`Máy này đã có tiến độ (${st.stats.a} câu). Gộp: mỗi từ giữ bản tiến xa hơn, không mất gì. Thay: dùng đúng bản sao lưu, bỏ tiến độ hiện tại trên máy này.`,
    buttons:[{label:'Gộp (khuyên dùng)',act:'restore-merge',primary:true},{label:'Thay bằng bản sao lưu',act:'restore-replace'},{label:'Huỷ',act:'mclose'}]});
}
async function restoreCode(code){
  if(/^\s*ELK-/i.test(code)) return syncJoin(code);
  try{ const x=await readCode(code); applyRestore(x,'mã sao lưu'); }
  catch(e){ toast('Mã không đúng. Hãy dán lại toàn bộ mã (bắt đầu bằng VL1: hoặc VL2:).'); }
}
/*<SYNC>*/
/* ---------- Đồng bộ nhiều máy (tuỳ chọn; docs/DANH-GIA-SO-VOI-THI-TRUONG.md tiêu chí 15) ----------
   Chỗ DUY NHẤT app gọi mạng (check-engine kiểm), và chỉ khi người học tự bật. Mã đồng bộ ELK-XXXX-… (100 bit ngẫu nhiên)
   là chìa khoá: ai có mã thì đọc/ghi được tiến độ đó; không tài khoản, không email, không tên. Máy chủ Supabase
   (supabase/migrations) chỉ lưu băm SHA-256 của mã và bản sao lưu nén (VL2). Mã nằm riêng ở localStorage SYNC_LS, không nằm
   trong tiến độ, mã sao lưu hay dữ liệu nghiên cứu. Gộp bằng mergeState (mỗi mục giữ bản tiến xa hơn); ghi có điều kiện theo rev
   nên hai máy ghi cùng lúc không đè nhau (máy sau đọc lại, gộp, rồi ghi). */
const SYNC = {url:'https://nlrcbmgixhpwxrvmklqc.supabase.co/rest/v1/rpc/', key:'sb_publishable_hvPJ4oI54CpvVNWonenFhQ_GkuSMhN2'};
const SYNC_LS = KEY+'-sync', SYNC_ABC = '0123456789ABCDEFGHJKMNPQRSTVWXYZ', SYNC_WAIT = 30000;
const syncKeyOk = k => /^ELK-[0-9A-HJKMNP-TV-Z]{4}(-[0-9A-HJKMNP-TV-Z]{4}){4}$/.test(k);
function syncNewKey(){ const b=new Uint8Array(20); crypto.getRandomValues(b); return 'ELK-'+[...b].map(x=>SYNC_ABC[x&31]).join('').match(/.{4}/g).join('-'); }
function syncGet(){ try{ const x=JSON.parse(localStorage.getItem(SYNC_LS)||'null'); return x&&syncKeyOk(x.k)?x:null; }catch(e){ return null; } }
function syncSet(x){ try{ x?localStorage.setItem(SYNC_LS,JSON.stringify(x)):localStorage.removeItem(SYNC_LS); }catch(e){} }
const SYNC_ST = {busy:false,err:''};
async function syncRpc(fn,body){
  const r=await fetch(SYNC.url+fn,{method:'POST',headers:{apikey:SYNC.key,'Content-Type':'application/json'},body:JSON.stringify(body)});
  if(!r.ok) throw new Error('http '+r.status); return r.json(); }
let _syncT=null;
function syncDirty(){ const s=syncGet(); if(!s) return; if(!s.dirty){ s.dirty=true; syncSet(s); } clearTimeout(_syncT); _syncT=setTimeout(()=>syncNow(),SYNC_WAIT); }
// Một vòng: đọc bản trên máy chủ → gộp nếu có bản mới hơn → ghi nếu máy này có thay đổi chưa gửi. Không gộp giữa lượt đang làm.
async function syncNow(){
  const s=syncGet(); if(!s||SYNC_ST.busy||(LOAD_ISSUE&&!LOAD_ISSUE.ok)) return;
  if(IN_VIEWER){ SYNC_ST.err='Trình xem artifact chặn kết nối mạng. Mở bản web của app để đồng bộ.'; return; }
  if(activeRun()){ clearTimeout(_syncT); _syncT=setTimeout(()=>syncNow(),SYNC_WAIT); return; }
  SYNC_ST.busy=true; SYNC_ST.err=''; let merged=false;
  try{
    for(let round=0;round<3;round++){
      const [row]=await syncRpc('el_pull',{k:s.k});
      if(row&&row.rev!==s.rev){ const x=sanitizeState(await readCode(row.data)); if(x&&x.words&&x.units){ st=mergeState(st,x); merged=true; } s.rev=row.rev; }
      if(!row) s.rev=0;
      if(!s.dirty&&row) break;
      const [p]=await syncRpc('el_push',{k:s.k,d:await makeCode(syncState()),base:s.rev});
      if(p&&!p.conflict){ s.rev=p.rev; s.dirty=false; break; }
    }
    s.at=Date.now(); syncSet(s);
    if(merged){ try{ localStorage.setItem(KEY,JSON.stringify(compactState())); }catch(e){} applySkin(); }
  }catch(e){ SYNC_ST.err='Chưa đồng bộ được (mất mạng hoặc máy chủ bận). App sẽ thử lại sau.'; }
  SYNC_ST.busy=false;
  if(merged||ui.view==='settings') render();
}
async function syncEnable(){ if(syncGet()) return; syncSet({k:syncNewKey(),rev:0,dirty:true,at:0}); evc('sync:on'); save(); await syncNow();
  toast(SYNC_ST.err||'Đã bật đồng bộ. Ghi lại mã để dùng trên máy khác.'); render(); }
async function syncJoin(k){
  k=String(k||'').trim().toUpperCase().replace(/\s+/g,''); if(!syncKeyOk(k)) return toast('Mã đồng bộ không đúng dạng ELK-XXXX-XXXX-XXXX-XXXX-XXXX.');
  if(IN_VIEWER) return toast('Trình xem artifact chặn kết nối mạng. Mở bản web của app để đồng bộ.');
  let row; try{ [row]=await syncRpc('el_pull',{k}); }catch(e){ return toast('Chưa kết nối được máy chủ. Kiểm tra mạng rồi thử lại.'); }
  if(!row) return toast('Không tìm thấy tiến độ nào với mã này. Kiểm tra lại từng ký tự.');
  const has=ALL_WORDS.some(w=>(st.words[w.id]||{}).learned)||st.stats.a>0;
  syncSet({k,rev:0,dirty:has,at:0}); evc('sync:join'); await syncNow();
  if(SYNC_ST.err) return toast(SYNC_ST.err);
  st.onboarded=true; save(); toast(has?'Đã gộp tiến độ của máy này với tiến độ đã đồng bộ.':'Đã tải tiến độ đã đồng bộ.'); go('path');
}
function syncOff(){ syncSet(null); clearTimeout(_syncT); toast('Đã tắt đồng bộ trên máy này. Tiến độ trên máy vẫn còn.'); render(); }
async function syncWipe(){ const s=syncGet(); if(!s) return;
  try{ await syncRpc('el_delete',{k:s.k}); }catch(e){ return toast('Chưa kết nối được máy chủ để xoá. Thử lại khi có mạng.'); }
  syncSet(null); toast('Đã xoá tiến độ trên máy chủ và tắt đồng bộ. Tiến độ trên máy này vẫn còn.'); render(); }
const syncLink = k => WEB_URL+'#sync='+k;
function syncPanel(){
  const s=syncGet(), ago=s&&s.at?Math.round((Date.now()-s.at)/60000):null;
  const head=`<h3>Đồng bộ nhiều máy</h3><p class="note">Học trên điện thoại và máy tính cùng một tiến độ, không cần tài khoản hay email. App tạo một <b>mã đồng bộ</b> bí mật; máy nào nhập mã đó thì dùng chung tiến độ. Máy chủ chỉ giữ bản tiến độ đã nén, không có tên hay email của bạn.</p>`;
  if(IN_VIEWER&&!s) return `<section class="panel stack">${head}<p class="note">Trình xem artifact chặn kết nối mạng, nên đồng bộ chỉ có ở <a href="${esc(WEB_URL)}" target="_blank" rel="noopener">bản web của app</a>. Chuyển tiến độ sang đó bằng mã sao lưu ở trên.</p></section>`;
  if(!s) return `<section class="panel stack">${head}
    <div class="row"><button class="btn primary" data-act="syncon">Bật đồng bộ</button></div>
    <form class="row" data-form="syncjoin" style="gap:8px"><input class="field" style="font:500 15px/1.3 var(--mono);flex:1 1 240px" placeholder="ELK-XXXX-XXXX-XXXX-XXXX-XXXX" aria-label="Mã đồng bộ" autocomplete="off" autocapitalize="characters"><button class="btn">Dùng mã đã có</button></form></section>`;
  return `<section class="panel stack">${head}
    <div class="setrow"><span>Mã đồng bộ của bạn</span><code class="num" style="font-size:15px;user-select:all">${esc(s.k)}</code></div>
    <p class="note">${SYNC_ST.busy?'Đang đồng bộ…':SYNC_ST.err?`<span class="warnt">${esc(SYNC_ST.err)}</span>`:ago==null?'Chưa đồng bộ lần nào.':`Đồng bộ gần nhất: ${ago<1?'vừa xong':ago<60?ago+' phút trước':Math.round(ago/60)+' giờ trước'}${s.dirty?' · còn thay đổi chưa gửi':''}.`}</p>
    <p class="note">Giữ mã này như mật khẩu: ai có mã thì xem và sửa được tiến độ của bạn. Mất mã thì tiến độ trên các máy vẫn còn, chỉ không đồng bộ được nữa.</p>
    <div class="row"><button class="btn" data-act="syncnow" ${SYNC_ST.busy?'disabled':''}>Đồng bộ ngay</button><button class="btn" data-act="synclink">Sao chép link cho máy khác</button></div>
    <div class="row"><button class="btn ghost" data-act="syncoff">Tắt trên máy này</button><button class="btn ghost" data-act="syncwipe">Xoá tiến độ trên máy chủ</button></div></section>`;
}
/*</SYNC>*/
// Lời nhắc qua Google Calendar: mở trang tạo sự kiện lặp lại hằng ngày (không cần tải file).
function gcalLink(){
  const [hh,mm]=(st.set.remind||'20:00').split(':').map(Number), d=new Date(), p=n=>String(n).padStart(2,'0');
  const day=`${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`, e=new Date(2000,0,1,hh,mm+15);
  const q=new URLSearchParams({action:'TEMPLATE',text:`Học từ vựng (${goal()} câu)`,details:'Mở English Ladder: ôn từ đến hạn trước, rồi học tiếp unit mới.',
    dates:`${day}T${p(hh)}${p(mm)}00/${day}T${p(e.getHours())}${p(e.getMinutes())}00`,recur:'RRULE:FREQ=DAILY'});
  return 'https://calendar.google.com/calendar/render?'+q.toString();
}
function importBackup(file){
  const r=new FileReader();
  r.onload=()=>{ try{
      const raw=JSON.parse(r.result), s0=raw&&raw.state?raw.state:raw;
      if(s0&&typeof s0.v==='number'&&s0.v>STATE_V) return toast(`File này do bản app mới hơn lưu (dữ liệu v${s0.v}, bản này đọc tới v${STATE_V}). Hãy mở bằng bản mới nhất: ${HOME_URL}`);
      applyRestore(migrate(s0),'file sao lưu');
    }catch(e){ toast('File không đúng định dạng sao lưu của English Ladder.'); } };
  r.readAsText(file);
}
// File lịch .ics: một sự kiện lặp lại hằng ngày có báo nhắc; mở bằng Lịch điện thoại/Google Calendar/Outlook.
function downloadReminder(){
  const [hh,mm]=(st.set.remind||'20:00').split(':'), d=new Date(), p=n=>String(n).padStart(2,'0');
  const day=`${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`;
  const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//English Ladder//VI','BEGIN:VEVENT',`UID:vocab-ladder-${Date.now()}@local`,
    `DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}Z`,`DTSTART:${day}T${p(hh)}${p(mm)}00`,'DURATION:PT15M','RRULE:FREQ=DAILY',
    `SUMMARY:Học từ vựng (${goal()} câu)`,'DESCRIPTION:Mở English Ladder: ôn từ đến hạn trước\, rồi học tiếp unit mới.',
    'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Đến giờ học từ vựng','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');
  download('nhac-hoc-tu-vung.ics',ics,'text/calendar');
}
function viewSettings(){ const html=viewSettings0();
  try{ const t=document.createElement('template'); t.innerHTML=html; const open=ui.setOpen||(ui.setOpen={'Mục tiêu mỗi ngày & nhắc học':true});
    [...t.content.children].forEach(sec=>{ if(sec.tagName!=='SECTION'||!sec.classList.contains('panel')) return;
      const h=sec.querySelector(':scope > h3, :scope > .spread > h3'); if(!h) return;
      const key=h.textContent.trim(), d=document.createElement('details'), sm=document.createElement('summary');
      d.className=sec.className; d.dataset.sec=key; if(open[key]) d.open=true; sm.appendChild(h.parentElement===sec?h:h.parentElement); d.appendChild(sm);
      while(sec.firstChild) d.appendChild(sec.firstChild); sec.replaceWith(d); });
    return t.innerHTML; }catch(e){ return html; } }
