const _cdActs31c = cdActs; cdActs = function(r,L){ if(r.t==='cv') return r.v.map(id=>({done:cdOk(((st.conv ||= {})[id]||{}).best), at:`data-act="cvgo" data-id="${id}"`, t:'Hội thoại mở: '+CVI[id].vi})); return _cdActs31c(r,L); };
