if(typeof location!=='undefined'&&/^#sync=/.test(location.hash||'')){ const k=decodeURIComponent(location.hash.slice(6)).toUpperCase(); try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){}
  if(syncKeyOk(k)&&!(syncGet()&&syncGet().k===k)){ ui.syncHash=k; setTimeout(()=>modal({ic:'🔄',title:'Dùng tiến độ đã đồng bộ?',sub:'Link này chứa mã đồng bộ tiến độ từ máy khác. Tiến độ trên máy này (nếu có) sẽ được gộp, không mất gì.',buttons:[{label:'Đồng bộ máy này',act:'syncjoinok',primary:true},{label:'Không',act:'mclose'}]}),300); } }
